class ConsentForm {
    constructor(containerSelector) {
        this.container = document.querySelector(containerSelector);
        this.state = {
            agreed: false,
            submitting: false,
        };
        this.render();
        this.attachEventListeners();
    }

    render() {
        this.container.innerHTML = `
            <div class="container">
                <div class="form-header">
                    <h1>Terms of Use</h1>
                    <p>Please review and agree to our terms of use to continue.</p>
                </div>

                <form id="consentForm">
                    <div class="success-message" id="successMessage">
                        ✓ Thank you! Your consent has been recorded.
                    </div>

                    <div class="form-field">
                        <input 
                            type="checkbox" 
                            id="termsCheckbox" 
                            name="terms" 
                            required
                            aria-required="true"
                            aria-describedby="termsHelp"
                        >
                        <div class="field-content">
                            <label for="termsCheckbox" class="field-label">
                                I agree to the terms of use
                                <span class="required">*</span>
                            </label>
                            <p class="helper-text" id="termsHelp">
                                By checking this box, you agree to our 
                                <a href="#" onclick="return false;">terms of use</a> and 
                                <a href="#" onclick="return false;">privacy policy</a>.
                            </p>
                        </div>
                    </div>

                    <div class="error-message" id="errorMessage"></div>

                    <div class="form-actions">
                        <button type="submit" class="btn-submit" id="submitBtn">
                            Accept &amp; Continue
                        </button>
                    </div>
                </form>
            </div>
        `;
    }

    attachEventListeners() {
        const form = document.getElementById('consentForm');
        const checkbox = document.getElementById('termsCheckbox');
        const submitBtn = document.getElementById('submitBtn');
        const errorMessage = document.getElementById('errorMessage');
        const successMessage = document.getElementById('successMessage');

        checkbox.addEventListener('change', (e) => {
            this.state.agreed = e.target.checked;
            errorMessage.classList.remove('show');
        });

        form.addEventListener('submit', (e) => {
            e.preventDefault();

            if (!this.state.agreed) {
                errorMessage.textContent = 'You must agree to the terms of use to continue.';
                errorMessage.classList.add('show');
                checkbox.focus();
                return;
            }

            this.handleSubmit(submitBtn, successMessage, errorMessage);
        });
    }

    async handleSubmit(submitBtn, successMessage, errorMessage) {
        this.state.submitting = true;
        submitBtn.disabled = true;
        submitBtn.textContent = 'Processing...';
        errorMessage.classList.remove('show');

        try {
            await new Promise((resolve) => setTimeout(resolve, 800));
            successMessage.classList.add('show');
            console.log('Form submitted successfully');

            setTimeout(() => {
                successMessage.classList.remove('show');
                this.state.submitting = false;
                submitBtn.disabled = false;
                submitBtn.textContent = 'Accept & Continue';
            }, 2500);
        } catch (error) {
            errorMessage.textContent = 'An error occurred. Please try again.';
            errorMessage.classList.add('show');
            this.state.submitting = false;
            submitBtn.disabled = false;
            submitBtn.textContent = 'Accept & Continue';
        }
    }
}

document.addEventListener('DOMContentLoaded', () => {
    new ConsentForm('#app');
});
